"""Straightforward reference implementation of PROTOCOL.md.

Deliberately naive (lists, dictionaries, deep copies) so that it can be
compared against the optimised engine.
"""
import copy


class RefRun:
    def __init__(self, cfg):
        self.M = cfg['banks']
        self.L = cfg['load_balancers']
        self.fifo_bytes = cfg['fifo_bytes']
        self.pifo_bytes = cfg['pifo_bytes']
        self.refill_batch = cfg['refill_batch']
        self.sample_period = cfg['sample_period']
        self.borders = list(cfg['borders'])
        self.U = self.borders[-1]
        spec = cfg['policy']
        self.kind = spec['kind']
        self.levels = {int(f): int(l) for f, l in spec.get('levels', [])}
        self.weights = {int(f): int(w) for f, w in spec.get('weights', [])}
        self.time = 0
        self.V = 0
        self.F = {f: 0 for f in self.weights}
        self.fifos = [[] for _ in range(self.M)]
        self.pifos = [[] for _ in range(self.M)]
        R = len(self.borders) - 1
        self.C = [[[1 if q < (r % self.M) else 0 for r in range(R)]
                   for q in range(self.M)] for _ in range(self.L)]
        self.H = [0] * R
        self.a = 0
        self.t = 0
        self.p = 0
        self.l = 0
        self.live = {}
        self.log = []
        self.saves = {}

    # -- policy ---------------------------------------------------------
    def assign_rank(self, pkt):
        if self.kind == 'fifo':
            self.time += 1
            return self.time
        if self.kind == 'sp':
            return self.levels[pkt['flow']]
        if self.kind == 'sff':
            return pkt['flow_size']
        weight = self.weights[pkt['flow']]
        base = max(self.F[pkt['flow']], self.V)
        value = base + -(-(pkt['length'] * 1048576) // weight)
        self.F[pkt['flow']] = value
        return value

    def post_service(self, rank):
        if self.kind == 'wfq' and rank > self.V:
            self.V = rank

    # -- helpers --------------------------------------------------------
    def classify(self, rank):
        value = min(rank, self.U - 1)
        for index in range(len(self.borders) - 1):
            if self.borders[index] <= value < self.borders[index + 1]:
                return index
        raise AssertionError('unclassified rank')

    def fifo_bytes_used(self, bank):
        return sum(p['length'] for p in self.fifos[bank])

    def pifo_bytes_used(self, bank):
        return sum(p['length'] for p in self.pifos[bank])

    # -- commands -------------------------------------------------------
    def enqueue(self, index, command):
        packet_id, flow, length, flow_size = command[1], command[2], command[3], command[4]
        pkt = {'id': packet_id, 'flow': flow, 'length': length,
               'flow_size': flow_size, 'rank': 0, 'ordinal': index,
               'lag': 0, 'stage': 'fifo', 'bank': 0}
        rank = self.assign_rank(pkt)
        pkt['rank'] = rank
        balancer = self.l
        self.l = (balancer + 1) % self.L
        interval = self.classify(rank)
        rows = self.C[balancer]
        bank = 0
        for q in range(1, self.M):
            if rows[q][interval] < rows[bank][interval]:
                bank = q
        accepted = self.fifo_bytes_used(bank) + length <= self.fifo_bytes
        if accepted:
            pkt['bank'] = bank
            self.fifos[bank].append(pkt)
            self.live[packet_id] = pkt
            self.C[balancer][bank][interval] += 1
            self.a += 1
        self.log.append([index, 'enqueue', packet_id, rank, balancer, interval,
                         bank, accepted])
        if accepted and self.a == self.sample_period:
            self.sample(index)

    def refill(self, bank):
        count = min(self.refill_batch, len(self.fifos[bank]))
        transferred = self.fifos[bank][:count]
        del self.fifos[bank][:count]
        for pkt in transferred:
            pkt['stage'] = 'pifo'
        self.pifos[bank].extend(transferred)
        candidates = sorted(self.pifos[bank], key=lambda x: (x['rank'], x['ordinal']))
        total = 0
        keep = []
        for pkt in candidates:
            if total + pkt['length'] <= self.pifo_bytes:
                total += pkt['length']
                keep.append(pkt)
            else:
                break
        evicted = candidates[len(keep):]
        self.pifos[bank] = list(keep)
        for pkt in evicted:
            del self.live[pkt['id']]
            pkt['stage'] = None
        return [pkt['id'] for pkt in reversed(evicted)]

    def service(self, index):
        old_t = self.t
        bank = self.p
        self.p = (bank + 1) % self.M
        self.t = old_t + 1
        if self.pifos[bank]:
            self._serve_from(index, old_t, bank)
            return
        evicted = self.refill(bank)
        if self.pifos[bank]:
            self._serve_after_refill(index, old_t, bank, evicted)
            return
        self.log.append([index, 'dequeue', old_t, bank, None, None, 0, 0, evicted])

    def _serve_from(self, index, old_t, bank):
        pkt = min(self.pifos[bank], key=lambda x: (x['rank'], x['ordinal']))
        self.pifos[bank].remove(pkt)
        del self.live[pkt['id']]
        self.post_service(pkt['rank'])
        evicted = self.refill(bank)
        self._finish_service(index, old_t, bank, pkt, evicted)

    def _serve_after_refill(self, index, old_t, bank, evicted):
        pkt = min(self.pifos[bank], key=lambda x: (x['rank'], x['ordinal']))
        self.pifos[bank].remove(pkt)
        del self.live[pkt['id']]
        self.post_service(pkt['rank'])
        self._finish_service(index, old_t, bank, pkt, evicted)

    def _finish_service(self, index, old_t, bank, pkt, evicted):
        rank_error = 0
        for other in self.live.values():
            if other['rank'] < pkt['rank']:
                rank_error += 1
        lag = pkt['lag']
        for other in self.live.values():
            if other['rank'] < pkt['rank']:
                other['lag'] += 1
        self.log.append([index, 'dequeue', old_t, bank, pkt['id'], pkt['rank'],
                         rank_error, lag, evicted])

    def sample(self, index):
        R = len(self.H)
        captured = []
        for r in range(R):
            total = 0
            for l in range(self.L):
                for q in range(self.M):
                    total += self.C[l][q][r]
            captured.append(total)
        for l in range(self.L):
            for r in range(R):
                minimum = min(self.C[l][q][r] for q in range(self.M))
                for q in range(self.M):
                    self.C[l][q][r] -= minimum
        self.H = [self.H[r] // 2 + captured[r] for r in range(R)]
        self.a = 0
        self.log.append([index, 'sample', captured, list(self.H)])

    def repartition(self, index, new_borders):
        old = self.borders
        new = [int(v) for v in new_borders]
        old_ranges = len(old) - 1
        new_ranges = len(new) - 1

        def clamp(value, low, high):
            return low if value < low else (high if value > high else value)

        def project(vector):
            out = []
            for j in range(new_ranges):
                total = 0
                for i in range(old_ranges):
                    b, c = old[i], old[i + 1]
                    span = c - b
                    mass = vector[i]
                    if mass:
                        hi = clamp(new[j + 1] - b, 0, span)
                        lo = clamp(new[j] - b, 0, span)
                        total += (mass * hi) // span - (mass * lo) // span
                out.append(total)
            return out

        self.C = [[project(self.C[l][q]) for q in range(self.M)]
                  for l in range(self.L)]
        self.H = project(self.H)
        self.borders = new
        self.log.append([index, 'repartition', new_ranges])

    def cancel(self, index, packet_id):
        pkt = self.live.get(packet_id)
        if pkt is None:
            self.log.append([index, 'cancel', packet_id, None, None, None])
            return
        stage = pkt['stage']
        bank = pkt['bank']
        lag = pkt['lag']
        if stage == 'pifo':
            self.pifos[bank] = [x for x in self.pifos[bank] if x is not pkt]
        else:
            self.fifos[bank] = [x for x in self.fifos[bank] if x is not pkt]
        del self.live[packet_id]
        self.log.append([index, 'cancel', packet_id, stage, bank, lag])

    def inspect(self, index, packet_id):
        pkt = self.live.get(packet_id)
        record = None
        if pkt is not None:
            record = [pkt['rank'], pkt['bank'], pkt['stage'], pkt['length'],
                      pkt['flow'], pkt['lag']]
        self.log.append([index, 'inspect', packet_id, record])

    def weight(self, index, flow, weight):
        self.weights[flow] = weight
        self.log.append([index, 'weight', flow, weight])

    def snapshot(self):
        state = copy.deepcopy({
            'fifos': self.fifos, 'pifos': self.pifos, 'C': self.C, 'H': self.H,
            'a': self.a, 't': self.t, 'p': self.p, 'l': self.l,
            'live': self.live, 'borders': self.borders, 'time': self.time,
            'V': self.V, 'F': self.F, 'weights': self.weights,
        })
        return state

    def restore(self, state):
        self.fifos = state['fifos']
        self.pifos = state['pifos']
        self.C = state['C']
        self.H = state['H']
        self.a = state['a']
        self.t = state['t']
        self.p = state['p']
        self.l = state['l']
        self.live = state['live']
        self.borders = state['borders']
        self.time = state['time']
        self.V = state['V']
        self.F = state['F']
        self.weights = state['weights']

    def save(self, index, name):
        self.saves[name] = self.snapshot()
        self.log.append([index, 'save', name])

    def restore_checkpoint(self, index, name):
        self.restore(self.saves[name])
        self.log.append([index, 'restore', name])

    def execute(self, events):
        for index, command in enumerate(events):
            name = command[0]
            if name == 'enqueue':
                self.enqueue(index, command)
            elif name == 'dequeue':
                for _ in range(command[1]):
                    self.service(index)
            elif name == 'sample':
                self.sample(index)
            elif name == 'repartition':
                self.repartition(index, command[1])
            elif name == 'cancel':
                self.cancel(index, command[1])
            elif name == 'inspect':
                self.inspect(index, command[1])
            elif name == 'weight':
                self.weight(index, command[1], command[2])
            elif name == 'save':
                self.save(index, command[1])
            elif name == 'restore':
                self.restore_checkpoint(index, command[1])
        return self.log

    def certificate(self):
        queues = []
        for bank in range(self.M):
            queues.append({
                'fifo': [p['id'] for p in self.fifos[bank]],
                'pifo': [p['id'] for p in self.pifos[bank]],
                'fifo_bytes': sum(p['length'] for p in self.fifos[bank]),
                'pifo_bytes': sum(p['length'] for p in self.pifos[bank]),
            })
        lags = sorted((pid, pkt['lag']) for pid, pkt in self.live.items())
        if self.kind == 'fifo':
            policy = {'kind': 'fifo', 'time': self.time}
        elif self.kind == 'sp':
            policy = {'kind': 'sp',
                      'levels': [[f, self.levels[f]] for f in sorted(self.levels)]}
        elif self.kind == 'sff':
            policy = {'kind': 'sff'}
        else:
            policy = {'kind': 'wfq', 'virtual_time': self.V,
                      'weights': [[f, self.weights[f]] for f in sorted(self.weights)],
                      'finish': [[f, self.F[f]] for f in sorted(self.F)]}
        return {
            'tick': self.t,
            'load_balancer': self.l,
            'service_bank': self.p,
            'sample_progress': self.a,
            'borders': list(self.borders),
            'counters': [[[v for v in row] for row in balancer]
                         for balancer in self.C],
            'history': list(self.H),
            'policy': policy,
            'queues': queues,
            'lags': [[pid, lag] for pid, lag in lags],
        }


def run_request(request):
    runs = []
    for cfg in request['runs']:
        run = RefRun(cfg)
        log = run.execute(cfg.get('events') or [])
        runs.append({'log': log, 'state': run.certificate()})
    return {'runs': runs}
PYEOF
cd /workspace/tmp/work && python3 -c "
